#include <map>
#include <memory>
#include <sstream>
#include <stdexcept>
#include <string>

class Expr {
 public:
  virtual ~Expr() = default;
  virtual double eval(const std::map<std::string, double>& vars) const = 0;
  virtual std::string str() const = 0;
  virtual std::unique_ptr<Expr> clone() const = 0;
};

using ExprPtr = std::unique_ptr<Expr>;

// A worked example.
class Num : public Expr {
 public:
  explicit Num(double v) : v_(v) {}
  double eval(const std::map<std::string, double>&) const override { return v_; }
  std::string str() const override {
    std::ostringstream out;
    out << v_;
    return out.str();
  }
  ExprPtr clone() const override { return std::make_unique<Num>(v_); }

 private:
  double v_;
};

