TEST("constants evaluate to themselves") {
  CHECK_EQ(num(2.5)->eval({}), 2.5);
  CHECK_EQ(num(2.5)->str(), std::string("2.5"));
}

TEST("variables look up their value") {
  CHECK_EQ(var("x")->eval({{"x", 4}}), 4.0);
  CHECK_EQ(var("x")->str(), std::string("x"));
}

TEST("an unbound variable throws out_of_range") {
  CHECK_THROWS(var("y")->eval({{"x", 1}}), std::out_of_range);
}

TEST("nested expressions evaluate") {
  // (1 + (x * 2)) with x = 5
  auto e = add(num(1), mul(var("x"), num(2)));
  CHECK_EQ(e->eval({{"x", 5}}), 11.0);
}

TEST("str() is fully parenthesised") {
  auto e = mul(add(var("a"), num(1)), add(var("b"), num(2)));
  CHECK_EQ(e->str(), std::string("((a + 1) * (b + 2))"));
}

TEST("clone is a deep, independent copy") {
  ExprPtr original = add(var("x"), num(3));
  ExprPtr copy = original->clone();
  CHECK(copy.get() != original.get());
  CHECK_EQ(copy->str(), original->str());
  original.reset();  // destroying the original must not affect the copy
  CHECK_EQ(copy->eval({{"x", 1}}), 4.0);
}

TEST("a long chain: 1 + 2 + ... + 100") {
  ExprPtr e = num(0);
  for (int i = 1; i <= 100; ++i) e = add(std::move(e), num(i));
  CHECK_EQ(e->eval({}), 5050.0);
}

