#include <map>
#include <memory>
#include <sstream>
#include <string>

class Expr {
 public:
  virtual ~Expr() = default;
  virtual double eval(const std::map<std::string, double>& vars) const = 0;
  virtual std::string str() const = 0;
  virtual std::unique_ptr<Expr> clone() const = 0;  // "virtual copy constructor"
};

using ExprPtr = std::unique_ptr<Expr>;

class Num : public Expr {
 public:
  explicit Num(double v) : v_(v) {}
  double eval(const std::map<std::string, double>&) const override { return v_; }
  std::string str() const override {
    std::ostringstream out;
    out << v_;
    return out.str();
  }
  ExprPtr clone() const override { return std::make_unique<Num>(v_); }

 private:
  double v_;
};

class Var : public Expr {
 public:
  explicit Var(std::string name) : name_(std::move(name)) {}
  double eval(const std::map<std::string, double>& vars) const override { return vars.at(name_); }  // at() throws out_of_range
  std::string str() const override { return name_; }
  ExprPtr clone() const override { return std::make_unique<Var>(name_); }

 private:
  std::string name_;
};

// Shared plumbing for two-operand nodes.
class Binary : public Expr {
 protected:
  Binary(ExprPtr l, ExprPtr r) : l_(std::move(l)), r_(std::move(r)) {}
  std::string wrap(const char* op) const { return "(" + l_->str() + " " + op + " " + r_->str() + ")"; }
  ExprPtr l_, r_;
};

class Add : public Binary {
 public:
  Add(ExprPtr l, ExprPtr r) : Binary(std::move(l), std::move(r)) {}
  double eval(const std::map<std::string, double>& vars) const override { return l_->eval(vars) + r_->eval(vars); }
  std::string str() const override { return wrap("+"); }
  ExprPtr clone() const override { return std::make_unique<Add>(l_->clone(), r_->clone()); }
};

class Mul : public Binary {
 public:
  Mul(ExprPtr l, ExprPtr r) : Binary(std::move(l), std::move(r)) {}
  double eval(const std::map<std::string, double>& vars) const override { return l_->eval(vars) * r_->eval(vars); }
  std::string str() const override { return wrap("*"); }
  ExprPtr clone() const override { return std::make_unique<Mul>(l_->clone(), r_->clone()); }
};

ExprPtr num(double v) { return std::make_unique<Num>(v); }
ExprPtr var(std::string name) { return std::make_unique<Var>(std::move(name)); }
ExprPtr add(ExprPtr l, ExprPtr r) { return std::make_unique<Add>(std::move(l), std::move(r)); }
ExprPtr mul(ExprPtr l, ExprPtr r) { return std::make_unique<Mul>(std::move(l), std::move(r)); }
